export const revalidate = 86400;

/**
 * GET /ads.txt
 *
 * Implements IAB ads.txt declaration dynamically driven by NEXT_PUBLIC_ADSENSE_CLIENT_ID.
 *
 * Security & Compliance Rules:
 * - If NEXT_PUBLIC_ADSENSE_CLIENT_ID is unset, empty, or invalid, returns a clean 404 response.
 * - Converts `ca-pub-XXXXXXXXXXXXXXXX` into `pub-XXXXXXXXXXXXXXXX`.
 * - Never returns dummy or mock publisher IDs that could trigger Google AdSense account flags.
 */
export async function GET() {
  const rawClientId = process.env.NEXT_PUBLIC_ADSENSE_CLIENT_ID?.trim() || "";

  // Validate format: must be `ca-pub-` or `pub-` followed by digits (typical length 10-20 digits)
  const pubMatch = rawClientId.match(/^(?:ca-)?(pub-\d{10,20})$/i);

  if (!pubMatch) {
    return new Response("Not Found", {
      status: 404,
      headers: {
        "Content-Type": "text/plain; charset=utf-8",
        "Cache-Control": "public, max-age=3600",
      },
    });
  }

  const publisherId = pubMatch[1].toLowerCase();
  const adsTxtContent = `google.com, ${publisherId}, DIRECT, f08c47fec0942fa0\n`;

  return new Response(adsTxtContent, {
    status: 200,
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=86400, s-maxage=86400",
    },
  });
}
